// GTPS Cloud Lua API reference (galing sa Gtps_Cloud_Latest.txt)
module.exports = "GTPS CLOUD — COMPLETE LUA API REFERENCE\nSource: https://beta.gtps.cloud/docs \nThis document is the FULL Lua scripting API for GTPS Cloud Growtopia private\nservers. It covers every Class, every Callback, every Global Function, and\nevery Utility module documented on the official site as of this snapshot.\n\nStructure of this document:\n  PART 1 — CALLBACKS        (event-driven functions you register)\n  PART 2 — GLOBAL FUNCTIONS (functions callable from anywhere, no prefix)\n  PART 3 — UTILITIES        (timer, http, file, dir, db, bit, require)\n  PART 4 — CLASSES          (Player, World, Tile, Item, ... one section each)\n\nConventions used below:\n  ClassName:methodName(params) -- description\n      Params: name (as documented)\n      Returns: <type>\n  For callbacks:\n  callbackName(function(param1, param2, ...) ... end)\n      Fires when: <description>\n      Params: <list>\n\n# PART 1 — CALLBACKS\n# Register these globally in your script. The server calls your function\n# automatically when the described event happens.\n\nonPlayerChatCallback(function(world, player, message) end)\nFires when: a player sends a chat message.\nParams: world, player, message\n\nonBestWorldEndCallback(function(world, score) end)\nFires when: a \"best world\" event/competition ends.\nParams: world, score\n\nonPlayerCommandCallback(function(world, player, command) end)\nFires when: a player runs a chat command (e.g. \"/something\").\nParams: world, player, command\n\nonPlayerDialogCallback(function(world, player, dialogName) end)\nFires when: a player responds to a dialog (this is the GLOBAL dialog\nresponse handler — fires for dialogs that don't use a per-call callback).\nParams: world, player, dialogName\n\nonPlayerLoginCallback(function(player) end)\nFires when: a player logs in.\nParams: player\n\nonPlayerFirstTimeLoginCallback(function(player) end)\nFires when: a player logs in for the very first time (new account).\nParams: player\n\nonPlayerRegisterCallback(function(world, player) end)\nFires when: a player registers a new account.\nParams: world, player\n\nonPlayerActionCallback(function(world, player, action) end)\nFires when: an \"action\" packet is received from a player.\nParams: world, player, action\n\nonPlayerEnterWorldCallback(function(world, player) end)\nFires when: a player enters a world.\nParams: world, player\n\nonPlayerValidateWorldCallback(function(world, player) end)\nFires when: the server validates a world for a player (pre-entry check).\nParams: world, player\n\nonPlayerLeaveWorldCallback(function(world, player) end)\nFires when: a player leaves a world.\nParams: world, player\n\nonPlayerDisconnectCallback(function(player) end)\nFires when: a player disconnects from the server.\nParams: player\n\nonPlayerDeathCallback(function(world, player, spikeKill) end)\nFires when: a player dies.\nParams: world, player, spikeKill\n\nonPlayerTradeCallback(function(world, player, targetPlayer) end)\nFires when: a player trade occurs.\nParams: world, player, targetPlayer\n\nonPlayerBoostClaimCallback(function(player) end)\nFires when: a player claims a boost.\nParams: player\n\nonPlayerTrashCallback(function(world, player, itemID, itemCount) end)\nFires when: a player trashes an item.\nParams: world, player, itemID, itemCount\n\nonPlayerRecycleCallback(function(world, player, itemID, itemCount, gems) end)\nFires when: a player recycles an item.\nParams: world, player, itemID, itemCount, gems\n\nonPlayerCrimeCallback(function(world, player, rewardID, rewardAmount) end)\nFires when: a player receives a \"crime\" reward.\nParams: world, player, rewardID, rewardAmount\n\nonPlayerSurgeryCallback(function(world, player, resultID, resultAmount, targetPlayer) end)\nFires when: a surgery result occurs.\nParams: world, player, resultID, resultAmount, targetPlayer\n\nonPlayerKillCallback(function(world, player, targetPlayer) end)\nFires when: one player kills another (PvP kill event).\nParams: world, player, targetPlayer\n\nonPlayerPunchPlayerCallback(function(world, player, targetPlayer) end)\nFires when: a player punches another player.\nParams: world, player, targetPlayer\n\nonPlayerPunchNPCCallback(function(world, player, npc) end)\nFires when: a player punches an NPC.\nParams: world, player, npc\n\nonPlayerProviderCallback(function(world, player, tile, itemID, itemAmount) end)\nFires when: a player collects from a \"provider\" block.\nParams: world, player, tile, itemID, itemAmount\n\nonPlayerHarmonicCallback(function(world, player, tile, itemID, amount) end)\nFires when: a player performs a harmonic action and gets rewarded.\nParams: world, player, tile, itemID, amount\n\nonPlayerGeigerCallback(function(world, player, itemID, amount) end)\nFires when: a player performs a Geiger action and gets rewarded.\nParams: world, player, itemID, amount\n\nonPlayerCatchGhostCallback(function(world, player, jarID, amount) end)\nFires when: a player catches a ghost.\nParams: world, player, jarID, amount\n\nonPlayerDNACallback(function(world, player, resultID, resultAmount) end)\nFires when: a DNA machine result is produced for a player.\nParams: world, player, resultID, resultAmount\n\nonPlayerXPCallback(function(world, player, amount) end)\nFires when: a player's XP changes.\nParams: world, player, amount\n\nonPlayerFirePutOutCallback(function(world, player, tile) end)\nFires when: a player puts out a fire tile.\nParams: world, player, tile\n\nonPlayerGemsObtainedCallback(function(world, player, amount) end)\nFires when: a player obtains gems.\nParams: world, player, amount\n\nonPlayerEarnGrowtokenCallback(function(world, player, progressAmount) end)\nFires when: a player earns Growtoken progress.\nParams: world, player, progressAmount\n\nonPlayerTrainFishCallback(function(world, player) end)\nFires when: a player trains a fish.\nParams: world, player\n\nonPlayerVariantCallback(function(player, variant, delay, netID) end)\nFires when: a variant packet is sent/processed for a player.\nParams: player, variant, delay, netID\n\nonPlayerRawPacketCallback(function(player, packet) end)\nFires when: a raw packet event happens for a player.\nParams: player, packet\n\nonServerReceiveRawPacketCallback(function(world, player, packet) end)\nFires when: the server receives a raw packet from a player.\nParams: world, player, packet\n\nonPlayerDropCallback(function(world, player, itemID, itemCount) end)\nFires when: a player drops an item.\nParams: world, player, itemID, itemCount\n\nonPlayerLevelUPCallback(function(world, player, level) end)\nFires when: a player levels up.\nParams: world, player, level\n\nonPlayerEquipClothingCallback(function(world, player, itemID) end)\nFires when: a player equips a clothing item (request).\nParams: world, player, itemID\n\nonPlayerUnequipClothingCallback(function(world, player, itemID) end)\nFires when: a player unequips a clothing item (request).\nParams: world, player, itemID\n\nonPlayerEquippedClothingCallback(function(world, player, itemID) end)\nFires when: a player's clothing equip is confirmed.\nParams: world, player, itemID\n\nonPlayerUnequippedClothingCallback(function(world, player, itemID) end)\nFires when: a player's clothing unequip is confirmed.\nParams: world, player, itemID\n\nonPlayerPickupItemCallback(function(world, player, itemID, itemCount) end)\nFires when: a player picks up an item.\nParams: world, player, itemID, itemCount\n\nonPlayerEnterDoorCallback(function(world, player, doorTarget, doorID) end)\nFires when: a player enters a door.\nParams: world, player, doorTarget, doorID\n\nonPlayerPlantCallback(function(world, player, tile) end)\nFires when: a player plants a seed on a tile.\nParams: world, player, tile\n\nonPlayerHarvestCallback(function(world, player, tile) end)\nFires when: a player harvests a tile.\nParams: world, player, tile\n\nonPlayerCatchFishCallback(function(world, player, rewardID, rewardAmount) end)\nFires when: a player catches fish / receives a fishing reward.\nParams: world, player, rewardID, rewardAmount\n\nonTileWrenchCallback(function(world, player, tile) end)\nFires when: a player uses a wrench on a tile.\nParams: world, player, tile\n\nonPlayerWrenchCallback(function(world, player, targetPlayer) end)\nFires when: a player uses a wrench on another player.\nParams: world, player, targetPlayer\n\nonPlayerBlessingClaimCallback(function(world, player, blessingID) end)\nFires when: a player claims a blessing.\nParams: world, player, blessingID\n\nonPlayerConvertItemCallback(function(world, player, itemID) end)\nFires when: a player converts an item.\nParams: world, player, itemID\n\nonPlayerAddFriendCallback(function(world, player, targetPlayer) end)\nFires when: a player adds another player as a friend.\nParams: world, player, targetPlayer\n\nonTileBreakCallback(function(world, player, tile) end)\nFires when: a tile is broken.\nParams: world, player, tile\n\nonTilePlaceCallback(function(world, player, tile, itemID) end)\nFires when: a player ATTEMPTS to place a tile (before placement completes).\nParams: world, player, tile, itemID\n\nonTilePlacedCallback(function(world, player, tile) end)\nFires when: tile placement COMPLETES.\nParams: world, player, tile\n\nonTilePunchCallback(function(world, player, tile) end)\nFires when: a tile is punched.\nParams: world, player, tile\n\nonPlayerConsumableCallback(function(world, player, tile, itemID, targetPlayer) end)\nFires when: a player uses a consumable item.\nParams: world, player, tile, itemID, targetPlayer\n\nonEventChangedCallback(function(eventID, oldEventID) end)\nFires when: the server's current event changes.\nParams: eventID, oldEventID\n\nonPlayerTick(function(player) end)\nFires when: on every player tick (repeated tick cycle per player).\nParams: player\n\nonWorldTick(function(world) end)\nFires when: on every world tick.\nParams: world\n\nonWorldLoaded(function(world) end)\nFires when: a world finishes loading (into memory).\nParams: world\n\nonWorldOffloaded(function(world) end)\nFires when: a world is unloaded from memory.\nParams: world\n\nonTick(function() end)\nFires when: on every server tick. No arguments.\n\nonDiscordMessageCreateCallback(function(event) end)\nFires when: a Discord message is created (bot sees it).\nParams: event (DiscordMessageCreateEvent — see Part 4)\n\nonDiscordButtonClickCallback(function(event) end)\nFires when: a Discord button is clicked.\nParams: event (DiscordButtonClickEvent — see Part 4)\n\nonDiscordFormSubmitCallback(function(event) end)\nFires when: a Discord modal/form is submitted.\nParams: event (DiscordFormSubmitEvent — see Part 4)\n\nonDiscordBotReadyCallback(function() end)\nFires when: the Discord bot becomes ready/connected. No arguments.\n\nonDiscordSlashCommandCallback(function(event) end)\nFires when: a Discord slash command is invoked.\nParams: event (DiscordSlashCommandEvent — see Part 4)\n\nonPlayerDungeonEntitySlainCallback(function(world, player, entityType) end)\nFires when: a player slays a dungeon entity.\nParams: world, player, entityType\n\nonPlayerStartopiaCallback(function(world, player, rewardID, rewardAmount, statusID) end)\nFires when: a Startopia reward event occurs.\nParams: world, player, rewardID, rewardAmount, statusID\n\nonPlayerPunchCallback(function(world, player, x, y) end)\nFires when: a player punches at specific coordinates.\nParams: world, player, x, y\n\nonPlayerCookingCallback(function(world, player, resultID, resultAmount, accuracy) end)\nFires when: a player finishes cooking.\nParams: world, player, resultID, resultAmount, accuracy\n\nonHTTPRequest(function(request) end)\nFires when: an incoming HTTP request hits your server's HTTP endpoint.\nMUST return a response table: { status = <num>, body = <string>,\nheaders = { [\"Content-Type\"] = \"text/plain\" } }\nParams: request  -- fields: request.method, request.path, request.body,\n                     request.headers[...]\nPublic URL format: https://api.gtps.cloud/g-api/{server_port}/...\nExample:\n    onHTTPRequest(function(req)\n        if req.method == \"get\" and req.path == \"/hello\" then\n            return { status = 200, body = \"Hello back\",\n                      headers = { [\"Content-Type\"] = \"text/plain\" } }\n        end\n        return { status = 404, body = \"Not found\", headers = {} }\n    end)\n\nonPlayerActivateTileCallback(function(world, player, tile) end)\nFires when: a player activates a tile.\nParams: world, player, tile\n\nonPlayerVendingBuyCallback(function(world, player, tile, itemID, itemCount) end)\nFires when: a player buys from a vending machine.\nParams: world, player, tile, itemID, itemCount\n\nonPlayerSpliceSeedCallback(function(world, player, tile, seedID) end)\nFires when: a player splices seeds.\nParams: world, player, tile, seedID\n\nonPlayerCardBattleCallback(function(world, player, targetPlayer, rewardID, rewardAmount) end)\nFires when: a player wins/receives a card battle reward.\nParams: world, player, targetPlayer, rewardID, rewardAmount\n\nonPlayerDepositCallback(function(world, player, tile, itemID, itemCount) end)\nFires when: a player deposits an item (e.g. into a storage block).\nParams: world, player, tile, itemID, itemCount\n\nonGetTileExtraDataCallback(function(world, tile, gameVersion, refPlayer) end)\nFires when: the server requests extra data for a tile.\nParams: world, tile, gameVersion, refPlayer\n\nonPlayerRoleChangedCallback(function(player, newRoleID, oldRoleID) end)\nFires when: a player's role changes.\nParams: player, newRoleID, oldRoleID\n\nonPlayerLoseCardBattleCallback(function(world, player, targetPlayer) end)\nFires when: a player loses a card battle.\nParams: world, player, targetPlayer\n\nonLeaderboardEndCallback(function(player, leaderboardType, rank) end)\nFires when: a leaderboard cycle ends for a player.\nParams: player, leaderboardType, rank\n\nonPlayerEarnAchievementCallback(function(world, player, achievementType) end)\nFires when: a player earns an achievement.\nParams: world, player, achievementType\n\nonPlayerSewCallback(function(world, player, resultID, resultAmount) end)\nFires when: a player sews and gets a reward result.\nParams: world, player, resultID, resultAmount\n\nonPlayerPetBattleCallback(function(world, player, targetPlayer) end)\nFires when: a player pet battle occurs.\nParams: world, player, targetPlayer\n\nonPlayerGemsChangedCallback(function(world, player, previousGems) end)\nFires when: a player's gem balance changes.\nParams: world, player, previousGems\n\nonPlayerCoinsChangedCallback(function(world, player, previousCoins) end)\nFires when: a player's coin balance changes.\nParams: world, player, previousCoins\n\nonPlayerPlaymodAddedCallback(function(player, modType, lastsForSeconds, applier) end)\nFires when: a playmod (buff/mod) is added to a player.\nParams: player, modType, lastsForSeconds, applier\n\nonPlayerPlaymodRemovedCallback(function(player, modType) end)\nFires when: a playmod is removed from a player.\nParams: player, modType\n\nonPlayerFishingStatusCallback(function(world, player, tile, status, itemID) end)\nFires when: a player's fishing status updates.\nParams: world, player, tile, status, itemID\n\nonPlayerStateChangedCallback(function(world, player, new_state, old_state) end)\nFires when: a player's state changes.\nParams: world, player, new_state, old_state\n\nonPlayerMovedCallback(function(world, player, current_x, current_y, previous_x, previous_y) end)\nFires when: a player moves.\nParams: world, player, current_x, current_y, previous_x, previous_y\n\n[END OF CALLBACKS — full list, ~90 callbacks total, matches the official\nCallbacks page exactly]\n\n# PART 2 — GLOBAL FUNCTIONS\n# Callable from anywhere in your script without a class prefix.\n\nregisterLuaPlaymod() -- Registers a Lua playmod. Returns: number\nregisterLuaCommand() -- Registers a Lua chat command. Returns: void\nregisterLuaEvent() -- Registers a custom server-wide event. Returns: void\nregisterLuaDailyEvent() -- Registers a custom daily event. Returns: void\nregisterLuaAchievement() -- Registers a custom achievement. Returns: void\nregisterLuaItem() -- Registers a custom item. Returns: void\n\ngetItem(itemID) -- Returns the Item for the given ID. Returns: Item\ngetItemsCount() -- Returns total registered items count. Returns: number\ngetMaxItems() -- Returns the max items limit. Returns: number\ngetRealGTItemsCount() -- Returns the count of \"real\" GT items. Returns: number\n\ngetServerPlayers() -- Returns all players on the server. Returns: {Player}\ngetServerWorlds() -- Returns all active worlds. Returns: {World}\ngetAllPlayers() -- Returns all players (preferred over getServerPlayers). Returns: {Player}\ngetAllWorlds() -- Returns all worlds. Returns: {World}\ngetAllGuilds() -- Returns all guilds. Returns: {Guild}\n\nreloadScripts() -- Reloads all Lua scripts. Returns: void\nreloadConfigs() -- Reloads server configs. Returns: void\nreloadItems() -- Reloads item definitions. Returns: void\n\ngetPlayer(userID) -- Returns the Player for a given user ID. Returns: Player\ngetPlayerByName(playerName, client) -- Returns the Player for a given name. Returns: Player\nsavePlayer() -- Manually saves a player to persistent storage. Returns: void\n\ngetActiveDailyOffers() -- Returns active daily store offers. Returns: {ShopItem}\ngetEventOffers() -- Returns current event store offers. Returns: {ShopItem}\ngetCurrentServerEvent() -- Returns the current server event ID. Returns: number\ngetCurrentServerDailyEvent() -- Returns the current daily event ID. Returns: number\ngetStoreItems() -- Returns all store items. Returns: {ShopItem}\ngetIOTMItem(itemID) -- Returns the IOTM object for an item ID. Returns: IOTM\ngetEasterBuyTime(userID) -- Returns Easter-event buy timestamp for a user. Returns: number\nisDailyOfferPurchased(userID, storeItemID) -- Checks purchase status. Returns: boolean\naddDailyOfferPurchased(userID, storeItemID) -- Marks a daily offer purchased. Returns: void\ngetEasterEggs(userID) -- Returns Easter egg count for a user. Returns: number\nformatStoreTime(targetTime, currentTime) -- Formats a store countdown string. Returns: string\n\ngetTopPlayerByBalance() -- Returns the richest player. Returns: Player\ngetTopWorldByVisitors() -- Returns the most-visited world. Returns: World\n\nprint() -- Prints to server console/log. Returns: void\n\ngetServerName() -- Returns the server's name. Returns: string\ngetServerID() -- Returns the server's ID. Returns: number\ngetNewsBanner() -- Returns the current news banner text/id. Returns: string\ngetNewsBannerDimensions() -- Returns news banner dimensions. Returns: string\ngetTodaysDate() -- Returns today's date. Returns: string\ngetTodaysEvents() -- Returns today's events. Returns: string\ngetMaxLevel() -- Returns the max player level. Returns: number\ngetCurrentEventDescription() -- Returns current event's description. Returns: string\ngetCurrentDailyEventDescription() -- Returns current daily event's description. Returns: string\ngetCurrentRoleDayDescription() -- Returns current \"role day\" description. Returns: string\nresetColor(message) -- Strips/resets color codes in a message. Returns: string\nformatTime(targetTime, currentTime) -- Formats a time difference into text. Returns: string\ngetAchievementsCount() -- Returns total achievements count. Returns: number\n\ngetWorld(WorldID) -- Returns the World for a given ID. Returns: World\ngetGuild(GuildID) -- Returns the Guild for a given ID. Returns: Guild\ngetWorldByName(worldName) -- Returns the World for a given name. Returns: World\nsaveWorld() -- Manually saves a world. Returns: void\nworldExists(worldName) -- Checks if a world exists. Returns: boolean\ngetActiveWorlds() -- Returns currently active (loaded) worlds. Returns: {World}\ngetCorruptedSouls(userID) -- Returns corrupted souls count for a user. Returns: number\n\nsaveDataToServer(uniqueID) -- Saves a Lua table under a key. Returns: void\nloadDataFromServer(uniqueID) -- Loads a Lua table by key. Returns: {any}\nsaveStringToServer(uniqueID, data) -- Saves a string value under a key. Returns: void\nloadStringFromServer(uniqueID) -- Loads a string value by key. Returns: string\n\naddWorldMenuWorld(world_id, display_name, decimal_color, is_priority) -- Adds a world to the world menu. Returns: void\nremoveWorldMenuWorld(world_id) -- Removes a world from the world menu. Returns: void\nhideWorldMenuDefaultSpecialWorlds(hide_default_special_worlds) -- Hides default special worlds in the menu. Returns: void\n\naddSocialPortalButton(button_data) -- Adds a button to the social portal UI. Returns: void\n  (NOTE: this fully resolves the earlier truncated entry — the official\n   signature takes a single `button_data` table parameter, no separate\n   callback argument is documented on the Global Functions page.)\n\ngetCurrencyShortName() -- Returns the currency's short name (e.g. \"gems\"). Returns: string\ngetCurrencyLongName() -- Returns the currency's long name. Returns: string\ngetCurrencyMediumName() -- Returns the currency's medium-length name. Returns: string\ngetCurrencyIcon() -- Returns the currency icon identifier. Returns: string\n\naddSidebarButton(sidebar_button) -- Adds a button to the sidebar UI. Returns: void\nremoveSidebarButton(sidebar_button_name) -- Removes a sidebar button by name. Returns: void\n\nparseText(str) -- Parses/tokenizes text and returns the processed result. Returns: {string}\n\ngetBlessingName(blessingID) -- Returns a blessing's name. Returns: string\ngetBlessingInfo(blessingID) -- Returns a blessing's info text. Returns: string\ngetBlessingRarity(blessingID) -- Returns a blessing's rarity. Returns: string\n\nsetGemEvent(boostGem) -- Sets the active gem-boost event multiplier. Returns: void\nsetXPEvent(boostXp) -- Sets the active XP-boost event multiplier. Returns: void\ngetGemEvent() -- Returns the current gem-boost multiplier. Returns: number\ngetXPEvent() -- Returns the current XP-boost multiplier. Returns: number\n\nsetEvent(event_id) -- Sets the current server event. Returns: void\nsetDailyEvent(daily_event_id) -- Sets the current daily event. Returns: void\n\nqueueRestart(in_seconds, full_restart, message) -- Schedules a server restart.\n  full_restart: 0 = soft restart, 1 = full restart. message: optional. Returns: void\n\ngetRoles() -- Returns all defined roles. Returns: {any}\ngetTitles() -- Returns all defined titles. Returns: {any}\ngetPlaymods() -- Returns all defined playmods. Returns: {any}\ngetHighestPriorityRole() -- Returns the highest-priority role definition. Returns: any\n\ngetEcoQuantity(itemID) -- Total item count in the whole economy (players+worlds). Returns: number\ngetEcoQuantityPlayers(itemID) -- Item count held by players only. Returns: number\ngetEcoQuantityWorlds(itemID) -- Item count present in worlds only. Returns: number\n\ncreateRedeemCode() -- Creates a redeem code (config passed as table — see Section\n  \"Redeem Code System\" example below). Returns: string\n\nsetPlaymodDuration(playmod_id, seconds) -- Changes a playmod's duration. Returns: void\nsetBroadcastWorld(worldName) -- Sets the world used by the global /go broadcast. Returns: void\ngetJimDailyQuest() -- Returns Jim's daily quest object (same for everyone). Returns: any\n\ndeleteAccount(id) -- ⚠️ EXPERIMENTAL, PERMANENT: deletes an account. Returns: void\ndeleteWorld(id) -- ⚠️ EXPERIMENTAL, PERMANENT: deletes a world. Returns: void\ndeleteGuild(id) -- ⚠️ EXPERIMENTAL, PERMANENT: deletes a guild. Returns: void\n\ngetServerDefaultPort() -- Returns the server's default port. Returns: number\n\ngetEvents() -- Returns all events (event.id, event.title, event.description, event.message). Returns: {any}\ngetDailyEvents() -- Returns all daily events (event.id, event.title, event.description). Returns: {any}\n\ngetItemEffects() -- Returns global item-effect definitions. Returns: {any}\ngetWorldEffects() -- Returns global world-effect definitions. Returns: {any}\ngetPlayerEffects() -- Returns global player-effect definitions. Returns: {any}\n\ngetRoleQuestDay() -- Returns the current role-quest day. Returns: number\ngetAchievements() -- Returns all achievement definitions. Returns: {any}\ngetMachineCaps() -- Returns all machine cap definitions. Returns: {any}\n\nhasFeatureEnabled(name) -- Checks whether a named feature flag is enabled. Returns: boolean\n\ncreateTemplate(backupName) -- Creates a world/server template snapshot. Returns: boolean\napplyTemplate(backupName) -- Applies a previously created template. Returns: boolean\ngetTemplates() -- Returns all saved templates. Returns: {any}\nhasTemplate(backupName) -- Checks whether a template exists. Returns: boolean\ndeleteTemplate(backupName) -- Deletes a template. Returns: boolean\n\nincludeClientFile(url, name) -- Registers/includes a client-side file for use. Returns: any\n\nenableCaching(item_id) -- Enables caching for an item/resource. Returns: void\ndisableCaching(item_id) -- Disables caching for an item/resource. Returns: void\n\n[END OF GLOBAL FUNCTIONS]\n\n# PART 3 — UTILITIES\n# Timer, HTTP, File I/O, Database, Bitwise, and Module utilities.\n\n--- Timer ---\ntimer.setTimeout(seconds, callback, ...)\n  Schedules `callback` to run once after `seconds`. Extra args (...) are\n  passed through to the callback. Returns: number (timerID)\n\ntimer.setInterval(seconds, callback, ...)\n  Schedules `callback` to repeat every `seconds`. Returns: number (timerID)\n\ntimer.clear(id)\n  Cancels a timeout or interval by its timerID.\n\n--- HTTP (outgoing requests) ---\nhttp.get(url)\n  Performs an async HTTP GET request. Params: url (string)\n\nhttp.post(url, post_data)\n  Performs an async HTTP POST request. Params: url (string), post_data (string)\n\n(For INCOMING HTTP requests to your server, see the onHTTPRequest callback\nin Part 1.)\n\n--- File ---\nfile.read(path) -- Reads a file from disk. Returns: string\nfile.write(path, data) -- Writes data to a file.\nfile.exists(path) -- Checks whether a file exists. Returns: boolean\nfile.delete(path) -- Deletes a file.\n\ndir.create(path) -- Creates a directory.\ndir.exists(path) -- Checks whether a directory exists. Returns: boolean\ndir.delete(path) -- Deletes a directory.\n\n--- Database (SQLite) ---\ndb.open(path) -- Opens a SQLite database handle. Returns: LuaDB\nLuaDB:query(query) -- Runs a SQL query against the database.\nLuaDB:close() -- Closes the database handle.\n\nExample:\n    local db = db.open(\"test1.db\")\n    db:query(\"CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, name TEXT)\")\n    local rows = db:query(\"SELECT * FROM users\")\n    db:close()\n\n--- Bitwise ---\nbit.band(a, b?) -- Bitwise AND. Returns: number\nbit.bor(a, b?) -- Bitwise OR. Returns: number\nbit.bxor(a, b?) -- Bitwise XOR. Returns: number\nbit.bnot(a) -- Bitwise NOT. Returns: number\nbit.lshift(a, b?) -- Left shift. Returns: number\nbit.rshift(a, b?) -- Logical right shift. Returns: number\nbit.arshift(a, b?) -- Arithmetic right shift. Returns: number\nbit.mod(a, b?) -- Bitmask modulo. Returns: number\n\n--- Module ---\nrequire(modname) -- Loads a Lua module through the sandboxed require.\n\n[END OF UTILITIES]\n\n# PART 4 — CLASSES\n\n## Player\nThe Player class represents a player. Use these methods to interact with\nplayer data, inventory, appearance, and more.\nPlayer:getName() -- Returns: string\nPlayer:enterWorld(worldName, notification, bypass) -- Returns: void\nPlayer:leaveWorld() -- Returns: void\nPlayer:punchBlock(x, y) -- Returns: void\nPlayer:placeBlock(x, y, itemID) -- Returns: void\nPlayer:getCleanName() -- Returns: string\nPlayer:getRealName() -- Returns: string\nPlayer:getRealCleanName() -- Returns: string\nPlayer:getTotalWorldLocks() -- Returns: number\nPlayer:getUserID() -- Returns: number\nPlayer:getPosX() -- Returns: number\nPlayer:getPosY() -- Returns: number\nPlayer:getBlockPosX() -- Returns: number\nPlayer:getBlockPosY() -- Returns: number\nPlayer:getMiddlePosX() -- Returns: number\nPlayer:getMiddlePosY() -- Returns: number\nPlayer:getNetID() -- Returns: number\nPlayer:hasMod(modID) -- Returns: boolean\nPlayer:hasRole(roleID) -- Returns: boolean\nPlayer:setRole(roleID) -- Returns: void\nPlayer:addMod(modID, value) -- Returns: void\nPlayer:removeMod(modID) -- Returns: void\nPlayer:getMod(modID) -- Returns: any\nPlayer:changeItem(itemID, itemCount, addBackpack) -- Returns: boolean\nPlayer:getItemAmount(itemID) -- Returns: number\nPlayer:getItemAmountBackpack(itemID) -- Returns: number\nPlayer:getXP() -- Returns: number\nPlayer:setXP(xp) -- Returns: void\nPlayer:removeXP(xp) -- Returns: void\nPlayer:getLevel() -- Returns: number\nPlayer:getStats(statType) -- Returns: number\nPlayer:setStats(statType, statNumber) -- Returns: void\nPlayer:getRequiredXP() -- Returns: number\nPlayer:getGems() -- Returns: number\nPlayer:addGems(gems, instantSet, progressQuests) -- Adds gems, updates display, optionally progresses gem-related quests. Returns: void\nPlayer:removeGems(gems, instantSet, progressQuests) -- Removes gems, updates display, optionally progresses quest logic. Returns: boolean\nPlayer:setGems(gems, instantSet) -- Returns: void\nPlayer:updateGems(instantSet) -- Refreshes the gem display on the client. Returns: void\nPlayer:getAutofarm() -- Returns: PlayerAutofarm\nPlayer:onConsoleMessage(message, delay) -- Returns: void\nPlayer:playAudio(message) -- Returns: void\nPlayer:onDialogRequest(message, delay) -- Returns: void\nPlayer:onStoreRequest(message, delay) -- Returns: void\nPlayer:onStorePurchaseResult(message, delay) -- Returns: void\nPlayer:onTalkBubble(netID, message, persistMessage, delay) -- Returns: void\nPlayer:onTextOverlay(message, delay) -- Returns: void\nPlayer:canFit() -- Returns: boolean\nPlayer:getCoins() -- Returns: number\nPlayer:addCoins(coins) -- Returns: void\nPlayer:setCoins(coins) -- Returns: void\nPlayer:removeCoins(coins, progressQuests) -- Returns: boolean\nPlayer:progressQuests(itemID, itemCount) -- Returns: void\nPlayer:upgradeInventorySpace(size) -- Returns: void\nPlayer:removeInventorySpace(size) -- Returns: void\nPlayer:setInventorySpace(newSize) -- Returns: void\nPlayer:isMaxInventorySpace() -- Returns: boolean\nPlayer:getInventorySize() -- Returns: number\nPlayer:onRedeemMenu() -- Returns: void\nPlayer:getWorldName() -- Returns: string\nPlayer:getWorld() -- Returns: World\nPlayer:onGrow4GoodDonate() -- Returns: void\nPlayer:getMods() -- Returns: {any}\nPlayer:getClothingItemID(index) -- Returns: number\nPlayer:getSubscription(subType) -- Returns: PlayerSubscription\nPlayer:addSubscription(Type, exp) -- Returns: PlayerSubscription\nPlayer:removeSubscription(type) -- Returns: void\nPlayer:getPlaytime() -- Returns: number\nPlayer:setPlaytime(time) -- Returns: void\nPlayer:addPlaytime(time) -- Returns: void\nPlayer:getAccountCreationTime() -- Returns: number\nPlayer:setAccountCreationTime(time) -- Returns: void\nPlayer:getAccountCreationDateStr() -- Returns: string\nPlayer:getTransformProfileButtons() -- Returns: string\nPlayer:onTradeHistoryUI(targetPlayer) -- Returns: void\nPlayer:onBackpackUI(targetPlayer) -- Returns: void\nPlayer:onMentorshipUI() -- Returns: void\nPlayer:onVouchersUI() -- Returns: void\nPlayer:onNameIconsUI(targetPlayer) -- Returns: void\nPlayer:onWrenchIconsUI(targetPlayer) -- Returns: void\nPlayer:onTitlesUI(targetPlayer) -- Returns: void\nPlayer:onAchievementsUI(targetPlayer) -- Returns: void\nPlayer:onClothesUI(targetPlayer) -- Returns: void\nPlayer:getClassicProfileContent(catType, flags) -- Returns: void\nPlayer:getDiscordID() -- Returns: string\nPlayer:onLinkDiscordUI() -- Returns: void\nPlayer:onUnlinkDiscordUI() -- Returns: void\nPlayer:getUnlockedAchievementsCount() -- Returns: number\nPlayer:getBackpackUsedSize() -- Returns: number\nPlayer:onFavItemsUI() -- Returns: void\nPlayer:onOnlineStatusUI() -- Returns: void\nPlayer:getOnlineStatus() -- Returns: number\nPlayer:onPersonalizeWrenchUI() -- Returns: void\nPlayer:getHomeWorldID() -- Returns: number\nPlayer:getProfileGuildInfo() -- Returns: string\nPlayer:getSubscriptionInfo() -- Returns: string\nPlayer:getCardBattleInfo() -- Returns: string\nPlayer:getProfileAccessButton() -- Returns: string\nPlayer:getProfileGuildJoinButton() -- Returns: string\nPlayer:onBillboardUI() -- Returns: void\nPlayer:onNotebookUI() -- Returns: void\nPlayer:onGrowpassUI() -- Returns: void\nPlayer:onGrowmojiUI() -- Returns: void\nPlayer:onGrow4GoodUI() -- Returns: void\nPlayer:onTradeScanUI() -- Returns: void\nPlayer:getGuildID() -- Returns: number\nPlayer:onGuildNotebookUI() -- Returns: void\nPlayer:onProfileUI(world, tab) -- Returns: void\nPlayer:onAddNotification(texture, message, audio, num, delay) -- Returns: void\nPlayer:onParticleEffect(particleID, posX, posY, num, num2, delay) -- Returns: void\nPlayer:setNextDialogRGBA(R, G, B, A) -- Returns: void\nPlayer:resetDialogColor() -- Returns: void\nPlayer:setNextDialogBorderRGBA(R, G, B, A) -- Returns: void\nPlayer:updateStats(world, type, amount) -- Returns: void\nPlayer:getCountry() -- Returns: string\nPlayer:setCountry(country) -- Returns: void\nPlayer:getPlatform() -- Returns: string\nPlayer:sendVariant(variantList) -- Sends a variant list packet to the online avatar. Returns: void\nPlayer:sendAction(action_str) -- Returns: void\nPlayer:getInventoryItems() -- Returns: {InventoryItem}\nPlayer:disconnect() -- Returns: void\nPlayer:sendRawPacket(data) -- Returns: void\nPlayer:getType() -- Returns: number (non-zero = NPC)\nPlayer:isFacingLeft() -- Returns: boolean\nPlayer:isOnline() -- Returns: boolean\nPlayer:addTitle(title_id) -- Returns: void\nPlayer:hasTitle(title_id) -- Returns: boolean\nPlayer:removeTitle(title_id) -- Returns: void\nPlayer:getActiveTitles() -- Returns: {any}\nPlayer:addActiveTitle(title_id) -- Returns: void\nPlayer:removeActiveTitle(title_id) -- Returns: void\nPlayer:addMail() -- Returns: void\nPlayer:clearMailbox() -- Returns: void\nPlayer:setNickname(nickname) -- Supports colors, spaces, '@'; persists across relogs. Returns: void\nPlayer:resetNickname() -- Returns: void\nPlayer:getBankBalance() -- Returns: number\nPlayer:addBankBalance(balance) -- Returns: void\nPlayer:removeBankBalance(balance) -- Returns: boolean\nPlayer:setBankBalance(balance) -- Returns: void\nPlayer:setCountryFlagForeground(item_id) -- Returns: void\nPlayer:setCountryFlagBackground(item_id) -- Returns: void\nPlayer:getCountryFlagForeground() -- Returns: number\nPlayer:getCountryFlagBackground() -- Returns: number\nPlayer:addLevel(level) -- Returns: void\nPlayer:removeLevel(level) -- Returns: void\nPlayer:setLevel(level) -- Returns: void\nPlayer:ban(modDuration, reason, punishedBy, banDevice, banIP) -- Returns: void\nPlayer:setRoleQuestLevel(type, newLevel) -- Returns: void\nPlayer:getRoleQuestLevel(type) -- Returns: number\nPlayer:getIP() -- Returns: string\nPlayer:getRID() -- Returns: string\nPlayer:setPassword(tankIDPass) -- Returns: void\nPlayer:getEmail() -- Returns: string\nPlayer:getBackpackItems() -- Returns: {InventoryItem}\nPlayer:getGender() -- Returns: number\nPlayer:hasActiveBlessing(blessingID) -- Returns: boolean\nPlayer:hasBlessing(blessingID) -- Returns: boolean\nPlayer:removeBlessing(blessingID) -- Returns: void\nPlayer:addBlessing(blessingID) -- Returns: void\nPlayer:checkPassword(password) -- Returns: boolean\nPlayer:getDiscordInvites() -- Returns: number\nPlayer:doAction(str) -- Returns: void\nPlayer:doRawPacket(data) -- Returns: void\nPlayer:getAltAccounts() -- Returns: {Player}\nPlayer:getRole() -- Returns: any\nPlayer:getTitles() -- Returns: {any}\nPlayer:getOwnedWorlds() -- Returns: {number}\nPlayer:getRecentWorlds() -- Returns: {number}\nPlayer:getAccessWorlds() -- Returns: {number}\nPlayer:getIPHistory() -- Returns: {string}\nPlayer:getRIDHistory() -- Returns: {string}\nPlayer:getSmallLockedWorlds() -- Returns: {number}\nPlayer:setBroadcastWorld(worldName) -- Returns: void\nPlayer:getFriends() -- Returns: {number}\nPlayer:addFriend(second_player) -- Returns: void\nPlayer:removeFriend(second_player) -- Returns: void\nPlayer:getLifeGoals() -- Returns: {any}\nPlayer:getBiweeklyQuests() -- Returns: {any}\nPlayer:getGrowpassPoints() -- Returns: number\nPlayer:addGrowpassPoints(points) -- Returns: void\nPlayer:setGrowpassPoints(points) -- Returns: void\nPlayer:adjustBlockHitCount(adjust) -- Adjust block break difficulty (-10 to +10). Returns: void\nPlayer:getAdjustedBlockHitCount() -- Returns: number\nPlayer:getPing() -- Returns: number\nPlayer:getDungeonScrolls() -- Returns: number\nPlayer:setDungeonScrolls(scrolls) -- Max 255. Returns: void\nPlayer:hasGrowID() -- Returns: boolean\nPlayer:addNote(note) -- Adds account note (visible in punishment UI). Returns: void\nPlayer:setAAPEnabled(aapEnabled) -- Requires linked Discord. Returns: void\nPlayer:setCustomAutofarmDelay(delay) -- Returns: void\nPlayer:getGameVersion() -- Returns: number\nPlayer:getItemEffects() -- Returns: any\nPlayer:visualPunch(tile) -- Returns: void\nPlayer:visualBuild(tile) -- Returns: void\nPlayer:getLastOnline() -- Returns: number\nPlayer:earnAchievement(type) -- Returns: void\nPlayer:getAchievements() -- Returns: {any}\nPlayer:getActivePet() -- Returns: any\nPlayer:getEffects() -- Returns: any\nPlayer:setEffects() -- Returns: void\nPlayer:deleteEffects() -- Returns: void\nPlayer:getOverlappingTiles() -- Returns: {Tile}\nPlayer:setLegendaryWizardTask(currentTaskNum) -- Returns: void\nPlayer:hasAccessToTile(tile, itemID, isSilent, ignoreReach) -- Returns: boolean\nPlayer:isPublicTile(tile) -- Returns: boolean\nPlayer:getState() -- Returns last registered state. Returns: number\nPlayer:hasRoleFlag(flag) -- Returns: boolean\n\nSubscription Types (used with Player:getSubscription / addSubscription):\n  TYPE_SUPPORTER = 0\n  TYPE_SUPER_SUPPORTER = 1\n  TYPE_YEAR_SUBSCRIPTION = 2\n  TYPE_MONTH_SUBSCRIPTION = 3\n  TYPE_GROWPASS = 4\n  TYPE_TIKTOK = 5\n  TYPE_BOOST = 6\n  TYPE_STAFF = 7\n  TYPE_FREE_DAY_SUBSCRIPTION = 8\n  TYPE_FREE_3_DAY_SUBSCRIPTION = 9\n  TYPE_FREE_14_DAY_SUBSCRIPTION = 10\n\n## World\nThe World class represents a Growtopia world. Use these methods to manage\ntiles, players, drops, and world properties.\nWorld:getName() -- Returns: string\nWorld:getOwner() -- Returns: Player\nWorld:setOwner(user_id) -- Returns: void\nWorld:removeOwner() -- Returns: void\nWorld:addPunishment(player, type, duration, reason, invoker_id) -- Returns: void\nWorld:removePunishment(player, type) -- Returns: void\nWorld:getPunishment(player, type) -- Returns: any\nWorld:getAllPunishments() -- Returns: {any}\nWorld:getID() -- Returns: number\nWorld:getTile(x, y) -- Returns: Tile\nWorld:spawnItem(x, y, itemID, itemCount, center_item) -- Returns: void\nWorld:spawnGems(x, y, gemsCount, player) -- Returns: void\nWorld:adjustGems(player, tile, gemsCount, noParticles) -- Returns: void\nWorld:onLoot(player, tile, gemsCount) -- Returns: void\nWorld:useItemEffect(netID, itemID, secondNetID, effectDelay) -- Returns: void\nWorld:useItemTileEffect(tile, netID, itemID, reverse, effectDelay) -- Returns: void\nWorld:getPlayers() -- Returns: {Player}\nWorld:getPlayersCount(show_all) -- Returns: number\nWorld:getVisiblePlayersCount() -- Returns: number\nWorld:isGameActive() -- Returns: boolean\nWorld:onGameWinHighestScore() -- Returns: void\nWorld:updateClothing(player) -- Returns: void\nWorld:onCreateChatBubble(posX, posY, message, persistMessage) -- Returns: void\nWorld:onCreateExplosion(posX, posY, radius, power) -- Returns: void\nWorld:setTileForeground(tile, id, visual_update, player) -- Returns: void\nWorld:setTileBackground(tile, id, visual_update, player) -- Returns: void\nWorld:getWorldSizeX() -- Returns: number\nWorld:getWorldSizeY() -- Returns: number\nWorld:getWorldType() -- Returns: number\nWorld:getTiles() -- Returns: {Tile}\nWorld:getEmptyTiles() -- Returns: {Tile}\nWorld:getNoCollisionTiles() -- Returns: {Tile}\nWorld:getDroppedItems() -- Returns: {Drop}\nWorld:getTileDroppedItems(tile) -- Returns: {Drop}\nWorld:addXP(player, xp_amount) -- Returns: void\nWorld:setPlayerPosition(player, x, y, no_packet) -- Returns: void\nWorld:removeDroppedItem(uid) -- Returns: void\nWorld:removeDroppedItemsByID(id) -- Returns: void\nWorld:removeAllDroppedItems() -- Returns: void\nWorld:updateTile(tile, player) -- Returns: void\nWorld:sendPlayerMessage(player, message) -- Returns: void\nWorld:punchTile(tile, player) -- Returns: void\nWorld:placeTile(tile, id, player) -- Returns: void\nWorld:hasTileAccess(player, tile) -- Returns: boolean\nWorld:hasAccess(player) -- Returns: boolean\nWorld:addTileAccess(player, tile) -- Returns: void\nWorld:addAccess(player, admin_type) -- Returns: void\nWorld:removeTileAccess(player, tile) -- Returns: void\nWorld:removeAllTileAccess() -- Returns: void\nWorld:removeAccess(player) -- Returns: void\nWorld:kill(player, force_respawn_on_white_door) -- Returns: void\nWorld:setClothing(player, item_id) -- Returns: void\nWorld:createNPC(name, x, y) -- Returns: Player\nWorld:removeNPC(player) -- Returns: void\nWorld:findNPCByName(name) -- Returns: {Player}\nWorld:getAllNPC() -- Returns: {Player}\nWorld:redeemCode(player, code) -- Returns: void\nWorld:setWeather(weatherID) -- Returns: void\nWorld:getWorldLock() -- Returns: Tile\nWorld:getMagplantRemoteTile(player) -- Returns: Tile\nWorld:setMagplantRemoteTile(player, tile) -- Returns: void\nWorld:hasFlag(flag) -- Returns: boolean\nWorld:addFlag(flag) -- Returns: void\nWorld:useConsumable(player, tile, id, noCallback) -- Returns: void\nWorld:spawnGhost(tile, id, sb, wd, sp) -- Returns: void\nWorld:findPathByTile(tile_1, tile_2, max_rad_x, max_rad_y) -- Returns: {any}\nWorld:isNuked() -- Returns: boolean\nWorld:nuke(ownerBanTime, adminsBanTime, everyoneElseBanTime) -- Returns: void\nWorld:removeNuke(unbanBannedUsers) -- Returns: void\n  World:getGuildID() -- Returns: number\nWorld:getMachineCap(item_id) -- Returns: number\nWorld:setMachineCap(item_id, item_count) -- Returns: void\nWorld:getMachineCaps() -- Returns: {any}\nWorld:removeMachineCap(item_id) -- Returns: void\nWorld:getEffects() -- Returns: {any}\nWorld:setEffects() -- Returns: void\nWorld:deleteEffects() -- Returns: void\nWorld:getCached(item_id) -- Returns: {Tile}\nWorld:delete() -- Returns: void\nWorld:save() -- Returns: void\nWorld:new(sizeX, sizeY, worldType) -- Creates a new world. Returns: World\nWorld:newFromTemplate(templateArg) -- Returns: World\nWorld:newFromGlobalTemplate(templateArg) -- Returns: World\n\n## Tile\nThe Tile class represents a single tile in a world.\nTile:getTileID() -- Returns: number\nTile:getTileItem() -- Returns: Item\nTile:getLastPunched() -- Returns: number\nTile:getPosX() -- Returns: number\nTile:getPosY() -- Returns: number\nTile:getNote() -- Returns: string\nTile:getTileForeground() -- Returns: number\nTile:getTileBackground() -- Returns: number\nTile:getTileData(data_type) -- Returns: any\nTile:setTileData(data_type, data_value) -- Returns: void\nTile:setTileDataInt(data_type, data_value) -- Returns: void\nTile:getFlags() -- Returns: number\nTile:setFlags(flags) -- Returns: void\n\n## Item\nThe Item class represents an item definition.\nItem:getPlaymods() -- Returns: {any}\nItem:getName() -- Returns: string\nItem:setName(value) -- Returns: void\nItem:getDescription() -- Returns: string\nItem:getID() -- Returns: number\nItem:getPrice() -- Returns: number\nItem:setPrice(newPrice) -- Returns: void\nItem:isObtainable() -- Returns: boolean\nItem:getInfo() -- Returns: {string}\nItem:getActionType() -- Returns: number\nItem:getRarity() -- Returns: number\nItem:getGems(world, player) -- Returns: number\nItem:getXP(world, player) -- Returns: number\nItem:getGrowTime() -- Returns: number\nItem:getCategoryType() -- Returns: number\nItem:getEditableType() -- Returns: number\nItem:setCategoryType(value) -- Returns: void\nItem:setEditableType(value) -- Returns: void\nItem:setGrowTime(value) -- Returns: void\nItem:setActionType(value) -- Returns: void\nItem:setDescription(value) -- Returns: void\nItem:getTexture() -- Returns: string\nItem:getTextureHash() -- Returns: number\nItem:setTextureHash(hash) -- Returns: void\nItem:getTextureX() -- Returns: number\nItem:getTextureY() -- Returns: number\nItem:setTexture(value) -- Returns: void\nItem:setTextureX(x) -- Returns: void\nItem:setTextureY(y) -- Returns: void\nItem:getClothingType() -- Returns: number\nItem:setClothingType(value) -- Returns: void\nItem:getPricedRarity() -- Returns: number\nItem:getEffects() -- Returns: any\nItem:setEffects() -- Returns: void\nItem:deleteEffects() -- Returns: void\nItem:getObtainability() -- Returns: string\nItem:getMachineCap() -- Returns: number\nItem:setMachineCap(value) -- Returns: void\nItem:removeMachineCap() -- Returns: void\nItem:getFarmability() -- Returns: boolean\nItem:setFarmability(value) -- Returns: void\nItem:getMaxFruitDropCount() -- Returns: number\nItem:getMinFruitDropCount() -- Returns: number\n\n## IOTM\nIOTM:getID() -- Returns: number\nIOTM:getAmount() -- Returns: number\nIOTM:setAmount(newAmount) -- Returns: void\n\n## Guild\nGuild:getTitle() -- Returns: string\nGuild:getDescription() -- Returns: string\nGuild:getNotebook() -- Returns: string\nGuild:getID() -- Returns: number\nGuild:getWorldID() -- Returns: number\nGuild:getXP() -- Returns: number\nGuild:getLevel() -- Returns: number\nGuild:getPoints() -- Returns: number\nGuild:getSettings() -- Returns: number\nGuild:getCreatedDate() -- Returns: number\nGuild:getMascotForegroundID() -- Returns: number\nGuild:getMascotBackgroundID() -- Returns: number\nGuild:getDisplayGuildMascot() -- Returns: number\nGuild:getOnlinePlayers() -- Returns: {Player}\n\n## ShopItem\nShopItem:getCategory() -- Returns: string\nShopItem:getTexture() -- Returns: string\nShopItem:getTexturePosX() -- Returns: number\nShopItem:getTexturePosY() -- Returns: number\nShopItem:getItemID() -- Returns: number\nShopItem:getTitle() -- Returns: string\nShopItem:getDescription() -- Returns: string\nShopItem:getPrice() -- Returns: number\nShopItem:isRPC() -- Returns: boolean\nShopItem:isGrowtoken() -- Returns: boolean\nShopItem:isVoucher() -- Returns: boolean\nShopItem:getRequiredEvent() -- Returns: number\nShopItem:getItemsDescription() -- Returns: string\nShopItem:getItems() -- Returns: {any}\nShopItem:makePurchaseItems(Count) -- Returns: {any}\nShopItem:getRollAmount() -- Returns: number\nShopItem:isRandom() -- Returns: boolean\n\n## GrowtopiaBot\nGrowtopiaBot:start() -- Returns: void\nGrowtopiaBot:onReceiveVariantCallback() -- Returns: void\nGrowtopiaBot:onReceiveTextCallback() -- Returns: void\nGrowtopiaBot:onReceiveRawCallback() -- Returns: void\nGrowtopiaBot:onReceiveTrackCallback() -- Returns: void\nGrowtopiaBot:sendStr(type, str) -- Returns: void\nGrowtopiaBot:sendRaw(data) -- Returns: void\nGrowtopiaBot:reconnect() -- Returns: void\nGrowtopiaBot:new() -- Returns: GrowtopiaBot\n\n## Drop\nDrop:getItemID() -- Returns: number\nDrop:getItemCount() -- Returns: number\nDrop:getPosX() -- Returns: number\nDrop:getPosY() -- Returns: number\nDrop:getUID() -- Returns: number\nDrop:getFlags() -- Returns: number\n\n## PlayerAutofarm\nPlayerAutofarm:isActive() -- Returns: boolean\nPlayerAutofarm:setActive() -- Returns: void\nPlayerAutofarm:getTargetBlockID() -- Returns: number\nPlayerAutofarm:setTargetBlockID(targetBlock) -- Returns: void\nPlayerAutofarm:isRotateLeft() -- Returns: boolean\nPlayerAutofarm:setIsRotateLeft() -- Returns: void\nPlayerAutofarm:getNextPosX() -- Returns: number\nPlayerAutofarm:setNextPosX(x) -- Returns: void\nPlayerAutofarm:getNextPosY() -- Returns: number\nPlayerAutofarm:setNextPosY(y) -- Returns: void\nPlayerAutofarm:getDelay() -- Returns: number\nPlayerAutofarm:setDelay(autofarmDelay) -- Returns: void\nPlayerAutofarm:isAutoCollectGems() -- Returns: boolean\nPlayerAutofarm:setIsAutoCollectGems() -- Returns: void\nPlayerAutofarm:getSlots() -- Returns: number\nPlayerAutofarm:setSlots(autofarmSlots) -- Returns: void\n\n## InventoryItem\nInventoryItem:getItemID() -- Returns: number\nInventoryItem:getItemCount() -- Returns: number\n\n## PlayerSubscription\nPlayerSubscription:getType() -- Returns: number\nPlayerSubscription:getExpireTime() -- Returns: number\nPlayerSubscription:getActivationTime() -- Returns: number\nPlayerSubscription:isPermanent() -- Returns: boolean\nPlayerSubscription:getNextRewardTime() -- Returns: number\n\n## DiscordBot\nDiscordBot:messageCreate(content, flags, type) -- Returns: void\nDiscordBot:directMessageCreate(content, flags, type) -- Returns: void\nDiscordBot:messageDelete() -- Returns: void\nDiscordBot:messageEdit(content, flags, type) -- Returns: void\nDiscordBot:globalCommandCreate(description) -- Returns: void\nDiscordBot:guildMemberSetNickname(nick) -- Returns: void\nDiscordBot:guildMemberRemoveRole() -- Returns: void\nDiscordBot:guildMemberAddRole() -- Returns: void\nDiscordBot:guildMemberGetRoles() -- Returns: {string}\n\n## DiscordButtonClickEvent\n(passed as `event` into onDiscordButtonClickCallback)\nDiscordButtonClickEvent:getCustomID() -- Returns: string\nDiscordButtonClickEvent:getPlayer() -- Returns: Player\nDiscordButtonClickEvent:getChannelID() -- Returns: string\nDiscordButtonClickEvent:getAuthorID() -- Returns: string\nDiscordButtonClickEvent:reply(content, flags) -- Returns: void\nDiscordButtonClickEvent:dialog() -- Returns: void\nDiscordButtonClickEvent:getMessageID() -- Returns: string\nDiscordButtonClickEvent:editOriginalResponse(content, flags) -- Returns: void\nDiscordButtonClickEvent:getRoles() -- Returns: {string}\n\n## DiscordFormSubmitEvent\n(passed as `event` into onDiscordFormSubmitCallback)\nDiscordFormSubmitEvent:getCustomID() -- Returns: string\nDiscordFormSubmitEvent:getPlayer() -- Returns: Player\nDiscordFormSubmitEvent:getChannelID() -- Returns: string\nDiscordFormSubmitEvent:getAuthorID() -- Returns: string\nDiscordFormSubmitEvent:getValue(id) -- Returns: string\nDiscordFormSubmitEvent:reply(content, flags) -- Returns: void\nDiscordFormSubmitEvent:getMessageID() -- Returns: string\nDiscordFormSubmitEvent:getRoles() -- Returns: {string}\n\n## DiscordMessageCreateEvent\n(passed as `event` into onDiscordMessageCreateCallback)\nDiscordMessageCreateEvent:getContent() -- Returns: string\nDiscordMessageCreateEvent:getPlayer() -- Returns: Player\nDiscordMessageCreateEvent:getChannelID() -- Returns: string\nDiscordMessageCreateEvent:getAuthorID() -- Returns: string\nDiscordMessageCreateEvent:isBot() -- Returns: boolean\nDiscordMessageCreateEvent:reply(content, flags, mention_replied_user) -- Returns: void\nDiscordMessageCreateEvent:getMentionedUsers() -- Returns: {string}\nDiscordMessageCreateEvent:getMessageID() -- Returns: string\nDiscordMessageCreateEvent:getRoles() -- Returns: {string}\n\n## DiscordSlashCommandEvent\n(passed as `event` into onDiscordSlashCommandCallback)\nDiscordSlashCommandEvent:getCommandName() -- Returns: string\nDiscordSlashCommandEvent:getParameter(parameter) -- Returns: string\nDiscordSlashCommandEvent:getPlayer() -- Returns: Player\nDiscordSlashCommandEvent:getChannelID() -- Returns: string\nDiscordSlashCommandEvent:getAuthorID() -- Returns: string\nDiscordSlashCommandEvent:reply(content, flags) -- Returns: void\nDiscordSlashCommandEvent:editOriginalResponse(content, flags) -- Returns: void\nDiscordSlashCommandEvent:dialog() -- Returns: void\nDiscordSlashCommandEvent:thinking(ephemeral) -- Returns: void\nDiscordSlashCommandEvent:getRoles() -- Returns: {string}\n\n## Font\nFont:loadFromFile(path) -- Returns: void\nFont:new() -- Returns: Font\n\n## RenderTexture\nRenderTexture:getWidth() -- Returns: number\nRenderTexture:getHeight() -- Returns: number\nRenderTexture:clear(r, g, b, a) -- Returns: void\nRenderTexture:saveToFile(path) -- Returns: void\nRenderTexture:draw() -- Returns: void\nRenderTexture:display() -- Returns: void\nRenderTexture:drawText(str, x, y, size, r, g, b, a) -- Returns: void\nRenderTexture:getTextSize(str, size) -- Returns: number\nRenderTexture:new(height) -- Returns: RenderTexture\n\n## Sprite\nSprite:setScale(x, y) -- Returns: void\nSprite:setPosition(x, y) -- Returns: void\nSprite:setRect(x, y, width, height) -- Returns: void\nSprite:setTexture() -- Returns: void\nSprite:new() -- Returns: Sprite\n\n## Texture\nTexture:loadFromFile(path) -- Returns: void\nTexture:new() -- Returns: Texture\n\n# PART 5 — EXTRA SYNTAX REFERENCE (from prior hands-on documentation notes,\n# not shown as separate class pages but essential to using the API above)\n\n--- Dialog String Syntax (used with Player:onDialogRequest / onPlayerDialogCallback) ---\nThe dialog string is built by concatenating pipe-delimited commands\nseparated by \"\\n\":\n\nBasic: set_default_color|Color , set_border_color|r,g,b,a| ,\n  set_bg_color|r,g,b,a| , set_custom_spacing|x:value;y:value| ,\n  add_custom_break| , start_custom_tabs| , end_custom_tabs| ,\n  disable_resize| , reset_placement_x|\n\nUI Elements: add_item_picker|name|message|placeholder| ,\n  add_player_info|name|level|exp|expRequired| ,\n  add_checkbox|name|message|checked| ,\n  add_friend_image_label_button|name|label|texture_path|size|texture_x|texture_y| ,\n  add_smalltext|message| ,\n  add_button_with_icon|big/small|label|flags|iconID|hoverNumber| ,\n  add_label_with_icon|size|message|alignment|iconID| ,\n  add_text_input|name|message|defaultInput|length| ,\n  add_spacer|size| , add_textbox|message| , add_quick_exit|\n\nAdvanced: embed_data|embed|data| ,\n  add_progress_bar|name|size|text|current|max|color| ,\n  add_image_button|name|imagePath|flags|open|label| ,\n  add_tab_button|name|label|iconPath|x|y| ,\n  add_banner|imagePath|x|y| , add_big_banner|imagePath|x|y|text|\n\nExample:\n    onPlayerLoginCallback(function(player)\n      local dialog = \"\"\n      dialog = dialog ..\n        \"set_default_color|`w`\\n\" ..\n        \"add_label|big|Welcome|left|\\n\" ..\n        \"add_textbox|Choose an option below:|\\n\" ..\n        \"add_button|btn_start|Start|noflags|0|0|\\n\" ..\n        \"add_quick_exit|\\n\"\n      player:onDialogRequest(dialog)\n    end)\n\n--- os library (⚠ dangerous, use with extreme caution) ---\nos.execute(command) -- ❌ can run arbitrary shell commands, never use with user input\nos.time() -- current time (epoch seconds)\nos.clock() -- CPU time used\nos.date(format, time?) -- formats a timestamp\nos.getenv(varname) -- read env var (⚠ may expose secrets)\nos.remove(filename) -- deletes a file, permanent\nos.rename(oldname, newname) -- rename/move a file\nos.setlocale(locale, category) -- set program locale\nos.exit(code?) -- ❌ terminates the Lua state/process immediately\n\n--- json library ---\njson.encode(dataTable) -- Lua table -> JSON string\njson.encode(data, 4) -- pretty-print with 4-space indent\njson.decode(jsonString) -- JSON string -> Lua table (nil if invalid)\n\n--- Lua Module system ---\nAdd \"-- MODULE\" as the first line of a file to make it requireable:\n    -- MODULE\n    local person = {}\n    function person.new(name)\n        local self = {name = name}\n        function self:say(msg) print(self.name .. \" says: \" .. msg) end\n        return self\n    end\n    return person\nThen elsewhere: local Person = require(\"example_module\")\n\n--- createRedeemCode() config table shape ---\n    local redeemData = {\n        redeemCode = \"SPECIAL123\",\n        obtainGems = 50,\n        obtainCoins = 1000,\n        obtainRole = 2,\n        redeemItems = { { id = 1001, count = 3 }, { id = 2002, count = 1 } },\n        maxUses = 5,\n        requireLevel = 10,\n        requireRole = 1,\n        requireGrowID = 1, -- 1=true, 0=false\n        requirePlaytime = 60,\n        requireAccountAge = 7,\n        redeemTitles = { { titleID = 5 }, { titleID = 9 } }\n    }\n    local result = createRedeemCode(redeemData)\n\nEND OF DOCUMENT\nCoverage: every URL the user provided (Player, World, Tile, Item, IOTM,\nGuild, ShopItem, GrowtopiaBot, Drop, PlayerAutofarm, InventoryItem,\nPlayerSubscription, DiscordBot, DiscordButtonClickEvent,\nDiscordFormSubmitEvent, DiscordMessageCreateEvent, DiscordSlashCommandEvent,\nFont, RenderTexture, Sprite, Texture, Callbacks, Global Functions,\nUtilities) was fetched directly from beta.gtps.cloud/docs and transcribed\nin full — nothing summarized or paraphrased away. Part 5 supplements this\nwith dialog-syntax / os / json / module details gathered from hands-on\nusage notes that aren't on their own doc page but are needed to actually\nuse the API (e.g. onDialogRequest's string syntax).";
